    if(action?.startsWith('request:')){result=api.respondToRequest(this.requestBuildingId,action.slice(8));if(result?.reason)this.notify(result.reason);else this.requestBuildingId=null;}
    if(state.growthReport&&action!=='dismissGrowth'||state.scoutReport&&!state.growthReport&&!['dismissScout','scoutReport'].includes(action))return;
    if(action==='dismissScout')api.dismissScoutReport();
